30	namespace andes_sim {
31	namespace {
32	
33	// One diagnostic row. status is PASS | FAIL | WARN | INFO; only PASS/FAIL/WARN
34	// feed the summary, and only FAIL gates the exit code.
35	struct Row {
36	  std::string name;
37	  std::string status;
38	  std::string detail;
39	};
40	
41	// Strip every leading and trailing `c` from `s` (mirrors Python str.strip(c)).
42	std::string strip_char(std::string s, char c) {
43	  size_t b = 0, e = s.size();
44	  while (b < e && s[b] == c) ++b;
45	  while (e > b && s[e - 1] == c) --e;
46	  return s.substr(b, e - b);
47	}
48	
49	// --- artifacts --------------------------------------------------------------
50	
51	std::vector<Row> doctor_artifacts() {
52	  const fs::path root = repo_root();
53	  struct A {
54	    const char* label;
55	    const char* env;
56	    fs::path def;
57	  };
58	  // Env overrides match hsim's _ARTIFACT_ENV so a test can simulate a missing
59	  // binary. Order (vsim, qemu, plugin) mirrors the golden's dict order.
60	  const A arts[] = {
61	      {"vsim", "VSIM_BIN", root / "verilator" / "build" / "sim_ax45mpv_premium"},
62	      {"qemu", "VSIM_QEMU", root / "build" / "qemu" / "qemu-system-riscv64"},
63	      {"plugin", "VSIM_PLUGIN", default_plugin_path()},
64	  };
65	  std::vector<Row> rows;
66	  for (const A& a : arts) {
67	    const char* ov = std::getenv(a.env);
68	    fs::path p = (ov && *ov) ? fs::path(ov) : a.def;
69	    if (fs::is_regular_file(p))
70	      rows.push_back({a.label, "PASS", p.string()});
71	    else
72	      rows.push_back(
73	          {a.label, "FAIL", "missing " + p.string() + " -- run ./andesim build"});
74	  }
