40	namespace fs = std::filesystem;
41	
42	namespace andes_sim {
43	namespace {
44	
45	// Resolve `path` to an absolute path. Returns the resolved string on success;
46	// on failure prints an error tagged with `ctx` and returns "".
47	std::string abs_elf(const std::string& path, const std::string& ctx) {
48	  std::error_code ec;
49	  std::string abs = fs::absolute(path, ec).string();
50	  if (ec) {
51	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
52	                 ctx.c_str(), path.c_str());
53	    return "";
54	  }
55	  return abs;
56	}
57	
58	// Validate the lone-ELF positional shape the standalone models require: print
59	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
60	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
61	// spawns a --describe subprocess per Verilator build). `model` labels the error.
62	int check_one_elf(const Cli& cli, const char* model) {
63	  if (cli.positional.empty()) {
64	    std::fprintf(stderr, "andesim run --mode %s: missing ELF\n", model);
65	    return 2;
66	  }
67	  if (cli.positional.size() > 1) {
68	    std::fprintf(stderr,
69	                 "andesim run --mode %s: unexpected argument '%s' "
70	                 "(engine args go after --)\n",
71	                 model, cli.positional[1].c_str());
72	    return 2;
73	  }
74	  return 0;
75	}
76	
77	// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
78	// single ELF, then exec the resolved engine standalone with `extra` (model
79	// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
80	// args verbatim (inherit stdio, no timeout, propagate exit code). The only
81	// per-model differences -- which engine, and how it is selected -- are resolved
82	// by the caller; `model` here only labels the positional diagnostics.
83	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
84	                   const char* model,
85	                   const std::vector<std::string>& extra = {}) {
86	  if (int rc = check_one_elf(cli, model)) return rc;
87	  // QEMU's -bios flag searches its data directory for relative paths rather
88	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
89	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
90	  if (elf.empty()) return 2;
91	  std::vector<std::string> args = extra;
92	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
93	  std::string err;
94	  int rc = run_passthrough(eng, "standalone", elf, args, err);
95	  if (!err.empty()) std::fprintf(stderr, "andesim run: %s\n", err.c_str());
96	  return rc;
97	}
98	
99	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
100	// only the built-in qemu descriptor, so it resolves that directly rather than
101	// discover_engines(), which would spawn a --describe subprocess per Verilator
102	// build only to discard them all here.
103	int run_fast(const Cli& cli) {
104	  // fast is QEMU-only; an explicit engine must name it.
105	  if (!cli.engine.empty() && cli.engine != "qemu") {
106	    std::fprintf(stderr,
107	                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
108	                 cli.engine.c_str());
109	    return 2;
110	  }
111	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
112	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
113	  std::string err;
114	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
115	  if (!err.empty()) {
116	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
117	    return 2;
118	  }
119	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
120	  if (cli.gdb) {
121	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
122	    extra.push_back("-gdb");
123	    extra.push_back("tcp::" + port);
124	    extra.push_back("-S");
125	  }
126	  return run_standalone(cli, builtin_qemu(), "fast", extra);
127	}
128	
129	// Defined below run_accurate; --cosim on the cycle model dispatches to it.
130	int run_cosim_lockstep(const Cli& cli, const EngineDescriptor& eng);
131	
132	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
133	// its --jtag-port only after it has reset and halted the hart, so the debugger we
134	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
135	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
136	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
137	// single debugger slot). Returns false on timeout.
138	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
139	  constexpr int kPollMs = 50;
140	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
141	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
142	      char line[512];
143	      while (std::fgets(line, sizeof line, f)) {
144	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
145	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
146	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
147	        unsigned lport = 0, st = 0;
148	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
149	            && st == 0x0A && lport == port) {
150	          std::fclose(f);
151	          return true;
152	        }
153	      }
154	      std::fclose(f);
155	    }
156	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
157	  }
158	  return false;
159	}
160	
161	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
162	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
163	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
164	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
165	  const char* iceman = std::getenv("ICEMAN");
166	  if (!iceman || !*iceman) {
167	    std::fprintf(stderr,
168	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
169	                 "(export ICEMAN=<path to ICEman binary>)\n");
170	    return 2;
171	  }
172	  // Build vsim argv from the standalone template, appending user passthrough
173	  // and the JTAG port flag.
174	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
175	  if (elf.empty()) return 2;
176	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
177	  std::vector<std::string> vsim_pass = cli.passthrough;
178	  vsim_pass.push_back("--jtag-port");
179	  vsim_pass.push_back(jtag_port);
180	  std::string err;
181	  const std::vector<std::string> vsim_argv =
182	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
183	  if (!err.empty()) {
184	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
185	    return 2;
186	  }
187	  std::fprintf(stderr,
188	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
189	               jtag_port.c_str());
190	  if (fork_background(vsim_argv) < 0) {
191	    std::fprintf(stderr,
192	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
193	    return 1;
194	  }
195	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
196	  // Wait for the port to be LISTENing before launching the debugger (it does not
197	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
198	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
199	  // but launch anyway if it never appears.
200	  if (const int pnum = std::atoi(jtag_port.c_str());
201	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
202	    std::fprintf(stderr,
203	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
204	                 "after 20s; launching the debugger anyway\n",
205	                 jtag_port.c_str());
206	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
207	  // localhost, port 9104) instead of its default real-hardware adapter; without
208	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
209	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
210	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
211	}
