213	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
214	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
215	// engine's own output. Unlike fast, this must discover the Verilator build(s)
216	// to resolve the engine (explicit --engine, else the sole one).
217	int run_accurate(const Cli& cli) {
218	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
219	  // --describe subprocess per Verilator build only to fail on the argument.
220	  if (int rc = check_one_elf(cli, "cycle")) return rc;
221	  // --mem-size is validated but has nothing to size: the cycle engine always
222	  // models its full DRAM window. Say so instead of silently ignoring it.
223	  if (!cli.mem_size.empty()) {
224	    std::string se;
225	    if (parse_size(cli.mem_size, se); !se.empty()) {
226	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
227	                   se.c_str());
228	      return 2;
229	    }
230	    std::fprintf(stderr,
231	                 "[andesim] --mem-size: the cycle engine models its full "
232	                 "DRAM window; nothing to size\n");
233	  }
234	  Discovery disc = discover_engines();
235	  std::string err;
236	  const EngineDescriptor* eng =
237	      resolve_accurate_engine(disc.engines, cli.engine, err);
238	  if (!eng) {
239	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
240	    // Surface why an expected engine may be absent (failed --describe, etc.).
241	    for (const std::string& w : disc.warnings)
242	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
243	    return 2;
244	  }
245	  // --cosim on the cycle model = lock-step DV co-sim against a QEMU oracle,
246	  // not a plain standalone run.
247	  if (cli.cosim) return run_cosim_lockstep(cli, *eng);
248	  if (cli.gdb) return run_cycle_gdb(cli, *eng);
249	  return run_standalone(cli, *eng, "cycle");
250	}
