252	// Parse --cosim-max-records: empty => 0 (unbounded; the oracle runs to program
253	// exit and defines the record count). Returns false + sets err on a bad value.
254	bool parse_cosim_max(const std::string& s, unsigned long long& out,
255	                     std::string& err) {
256	  out = 0;
257	  if (s.empty()) return true;
258	  char* end = nullptr;
259	  out = std::strtoull(s.c_str(), &end, 10);
260	  if (!end || *end != '\0') {
261	    err = "--cosim-max-records: want a non-negative integer, got '" + s + "'";
262	    return false;
263	  }
264	  return true;
265	}
