267	// `run --mode cycle --cosim`: lock-step DV co-sim (cosim_redesign F6, usage
268	// 1). Two independent boots of the same ELF -- the QEMU oracle (golden) and
269	// the vsim DUT -- each drain one full record per execution attempt from the
270	// arm pc; the streams are aligned by attempt index and diffed to localize the
271	// first diverging instruction. No handoff, no shared mmap. The oracle runs
272	// first (MHz-fast, defines the record count K); the DUT is then bounded to K
273	// so a diverged hart cannot run away.
274	int run_cosim_lockstep(const Cli& cli, const EngineDescriptor& eng) {
275	  auto fail = [](const std::string& msg) {
276	    std::fprintf(stderr, "andesim run --mode cycle --cosim: %s\n",
277	                 msg.c_str());
278	    return 2;
279	  };
280	  if (int rc = check_one_elf(cli, "cycle")) return rc;
281	
282	  std::error_code ec;
283	  const fs::path elf = fs::absolute(cli.positional[0], ec);
284	  if (ec || !fs::is_regular_file(elf, ec))
285	    return fail("ELF not found: " + cli.positional[0]);
286	  const std::string elf_path = elf.string();
287	
288	  // Arm pc: --pc-start (symbol or 0x addr) overrides the ELF entry default.
289	  std::string err;
290	  uint64_t arm_pc = 0;
291	  if (cli.pc_start.empty()) {
292	    arm_pc = elf_entry(elf_path, err);
293	    if (!err.empty()) return fail(err);
294	  } else {
295	    const std::string hex = resolve_pc(elf_path, cli.pc_start, err);
296	    if (!err.empty()) return fail(err);
297	    arm_pc = std::strtoull(hex.c_str(), nullptr, 16);
298	  }
299	  char arm_buf[32];
300	  std::snprintf(arm_buf, sizeof(arm_buf), "0x%llx",
301	                static_cast<unsigned long long>(arm_pc));
302	
303	  unsigned long long max_records = 0;
304	  if (!parse_cosim_max(cli.cosim_max_records, max_records, err))
305	    return fail(err);
306	
307	  // Workdir for the two record streams (removed on exit).
308	  const fs::path wd =
309	      fs::temp_directory_path() /
310	      ("andes-cosim-ls-" + std::to_string(::getpid()));
311	  fs::create_directories(wd, ec);
312	  const std::string oracle_stream = (wd / "oracle.ckpts").string();
313	  const std::string dut_stream = (wd / "dut.ckpts").string();
314	  auto cleanup = [&] { fs::remove_all(wd, ec); };
315	
316	  // Lock-step is slow on the DUT (a DMI step + full drain per attempt, tens
317	  // of attempts/s); give both legs a generous ceiling. --cosim-max-records
318	  // bounds the work; the timeout is only the runaway backstop.
319	  constexpr int kTimeoutMs = 1800 * 1000;
320	
321	  // ---- Leg 1: QEMU oracle (golden). Standalone andes machine + the
322	  // lock-step plugin; outfile IS the record stream. vlen syncs from the DUT
323	  // engine so the V-state widths match. ----
324	  const std::string plugin = [&] {
325	    if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return std::string(p);
326	    return default_plugin_path().string();
327	  }();
328	  std::string plugin_arg = plugin + ",outfile=" + oracle_stream +
329	                           ",lockstep_pc=" + arm_buf;
330	  if (max_records != 0)
331	    plugin_arg += ",lockstep_max=" + std::to_string(max_records);
332	
333	  const std::string vlen = std::to_string(synced_vlen(eng.vlen));
334	  std::vector<std::string> qemu_argv = {
335	      builtin_qemu().bin_path, "-machine", "andes_ae350", "-cpu",
336	      "andes-ax45mpv,vlen=" + vlen, "-nographic", "-semihosting-config",
337	      "enable=on,target=native", "-bios", elf_path, "-plugin", plugin_arg};
338	
339	  std::fprintf(stderr,
340	               "[andesim] cosim lock-step: oracle (QEMU) boots from reset, "
341	               "arms at %s\n",
342	               arm_buf);
343	  const RunResult qr = run_process(qemu_argv, kTimeoutMs);
344	  if (qr.spawn_failed) { cleanup(); return fail("oracle: failed to spawn QEMU"); }
345	  if (qr.timed_out) { cleanup(); return fail("oracle: timed out"); }
346	  if (!qr.out.empty()) std::fwrite(qr.out.data(), 1, qr.out.size(), stdout);
347	
348	  const StateStream oracle = read_state_stream(oracle_stream);
349	  if (!oracle.ok()) { cleanup(); return fail("oracle: " + oracle.error); }
350	  if (oracle.records.empty()) {
351	    cleanup();
352	    return fail("oracle produced no records (arm pc " + std::string(arm_buf) +
353	                " never reached?)");
354	  }
355	  const unsigned long long k = oracle.records.size();
356	  std::fprintf(stderr,
357	               "[andesim] cosim lock-step: oracle drained %llu record(s); "
358	               "DUT (vsim) bounded to the same\n",
359	               k);
360	
361	  // ---- Leg 2: vsim DUT, bounded to the oracle's K records. ----
362	  std::vector<std::string> vsim_argv = {
363	      eng.bin_path,         elf_path,
364	      "--cosim-lockstep",   "--cosim-out",
365	      dut_stream,           "--cosim-arm-pc",
366	      arm_buf,              "--cosim-max-records",
367	      std::to_string(k)};
368	  const RunResult vr = run_process(vsim_argv, kTimeoutMs);
369	  if (vr.spawn_failed) { cleanup(); return fail("DUT: failed to spawn vsim"); }
370	  if (vr.timed_out) { cleanup(); return fail("DUT: timed out"); }
371	  if (!vr.out.empty()) std::fwrite(vr.out.data(), 1, vr.out.size(), stdout);
372	
373	  const StateStream dut = read_state_stream(dut_stream);
374	  if (!dut.ok()) { cleanup(); return fail("DUT: " + dut.error); }
375	
376	  // ---- Compare ----
377	  const LockstepResult cmp = compare_lockstep_streams(oracle.records, dut.records);
378	  cleanup();
379	
380	  if (!cmp.diverged) {
381	    std::printf(
382	        "[cosim] PASS: %zu records match (lock-step, 1 attempt/record)\n",
383	        cmp.matched);
384	    return 0;
385	  }
386	
387	  if (!cmp.length_mismatch.empty()) {
388	    std::fprintf(stderr, "[cosim] FAIL: %s\n", cmp.length_mismatch.c_str());
389	    std::fprintf(stderr,
390	                 "        first divergence is a control-flow split at attempt "
391	                 "%zu (after %zu matching)\n",
392	                 cmp.record, cmp.matched);
393	    return 1;
394	  }
395	
396	  const std::string osym = symbolize(elf_path, cmp.oracle_pc);
397	  const std::string dsym = symbolize(elf_path, cmp.dut_pc);
398	  std::fprintf(stderr,
399	               "[cosim] FAIL: first divergence at attempt %zu (after %zu "
400	               "matching)\n",
401	               cmp.record, cmp.matched);
402	  std::fprintf(stderr, "        pc  vsim=0x%llx  qemu=0x%llx%s%s\n",
403	               static_cast<unsigned long long>(cmp.dut_pc),
404	               static_cast<unsigned long long>(cmp.oracle_pc),
405	               dsym.empty() ? "" : ("   (" + dsym + ")").c_str(),
406	               (!osym.empty() && osym != dsym) ? (" oracle=(" + osym + ")").c_str()
407	                                               : "");
408	  for (const FieldDiff& d : cmp.diff.diffs)
409	    std::fprintf(stderr, "        %-8s vsim=0x%llx  qemu=0x%llx\n",
410	                 d.field.c_str(), d.got, d.ref);
411	  return 1;
412	}
