414	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
415	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
416	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
417	// driver's tests/e2e.sh delegation with a single window-cycle line.
418	int run_hybrid(const Cli& cli) {
419	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
420	  auto fail = [](const std::string& msg) {
421	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
422	    return 2;
423	  };
424	
425	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
426	
427	  // Resolve to an absolute, existing path: a clean error beats a downstream
428	  // spawn failure, and pc-trigger resolution reads the ELF's .symtab.
429	  std::error_code ec;
430	  const fs::path elf = fs::absolute(cli.positional[0], ec);
431	  if (ec || !fs::is_regular_file(elf, ec))
432	    return fail("ELF not found: " + cli.positional[0]);
433	  const std::string elf_path = elf.string();
434	
435	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
436	  // mistake fails fast without spawning a --describe per Verilator build.
437	  std::string err;
438	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
439	  if (!err.empty()) return fail(err);
440	
441	  // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
442	  // hybrid triggers; simpoint/unknown returned an error above) -- exactly the
443	  // entry boundary --verify/--cosim need the oracle to arm on.
444	  unsigned long long cosim_interval = 10000;  // default per docs/archive/cosim_roi.md
445	  if (cli.cosim && !cli.cosim_interval.empty()) {
446	    char* end = nullptr;
447	    cosim_interval = std::strtoull(cli.cosim_interval.c_str(), &end, 10);
448	    if (!end || *end != '\0' || cli.cosim_interval.empty() ||
449	        cosim_interval == 0)
450	      return fail("--cosim-interval: want a positive integer, got '" +
451	                  cli.cosim_interval + "'");
452	  }
453	
454	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
455	  if (!err.empty()) return fail(err);
456	
457	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
458	  if (!cli.mem_size.empty()) {
459	    std::string se;
460	    mem = parse_size(cli.mem_size, se);
461	    if (!se.empty()) return fail("--mem-size: " + se);
462	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
463	    // guest RAM here. The physical mmap reserves one V-scratch page above the
464	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
465	    // page. Failing now beats allocating a huge mmap file first and letting
466	    // QEMU die late.
467	    if (mem > max_program_mem_bytes())
468	      return fail("--mem-size " + cli.mem_size +
469	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
470	                  "reservation)");
471	  }
472	
473	  // L26/F3: refuse a run whose static image would extend into the reserved
474	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
475	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
476	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
477	  // scratch -> silent corruption. Derive the page's start from
478	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
479	  // `mem`, so the threshold tracks the reservation shape instead of relying on
480	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
481	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
482	  // reports it.
483	  {
484	    std::string e;
485	    const uint64_t top = elf_load_top(elf_path, e);
486	    const uint64_t scratch_gpa =
487	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
488	    if (e.empty() && top > scratch_gpa) {
489	      char msg[256];
490	      std::snprintf(msg, sizeof(msg),
491	                    "ELF static image ends at 0x%llx, overlapping the reserved "
492	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
493	                    "; raise --mem-size or shrink the image",
494	                    static_cast<unsigned long long>(top),
495	                    static_cast<unsigned long long>(scratch_gpa));
496	      return fail(msg);
497	    }
498	  }
499	
500	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
501	  // or the sole cycle-accurate engine (reusing the F8 selector).
502	  Discovery disc = discover_engines();
503	  const EngineDescriptor* acc =
504	      resolve_accurate_engine(disc.engines, cli.engine, err);
505	  if (!acc) {
506	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
507	    for (const std::string& w : disc.warnings)
508	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
509	    return 2;
510	  }
511	
512	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
513	  // cannot share architectural state with the rv64 fast leg).
514	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
515	
516	  Plan plan;
517	  plan.elf = elf_path;
518	  plan.mem_size = mem;
519	  Step qemu_step{"qemu", "fast-leg", trig};
520	  Step vsim_step{acc->id, "accurate-leg", trig};
521	  vsim_step.extra_args = std::move(vsim_extras);  // kanata + warmup, validated
522	  if (cli.cosim) {
523	    // Orthogonal to the trigger: the vsim leg drains a resumable checkpoint
524	    // to the <state_out>.ckpts stream every N retires (run_plan reads them
525	    // back).
526	    vsim_step.extra_args.push_back("--hybrid-cosim");
527	    vsim_step.extra_args.push_back(std::to_string(cosim_interval));
528	  }
529	  plan.steps = {qemu_step, vsim_step};
530	
531	  // Banner to stderr so the window-cycle result stands alone on stdout.
532	  // vlen is the synced value the fast leg inherits from the engine.
533	  std::fprintf(stderr,
534	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
535	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
536	               elf.stem().string().c_str());
537	
538	  const PlanResult r = run_plan(plan, disc.engines);
539	  if (!r.ok()) {
540	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
541	    return 1;
542	  }
543	  // Relay each leg's stdout verbatim: the program's own prints (QEMU1 phase-1
544	  // output, then anything the ROI wrote on vsim) belong to the user.
545	  for (const PhaseResult& p : r.phases)
546	    if (!p.out.empty()) std::fwrite(p.out.data(), 1, p.out.size(), stdout);
547	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
548	  // vsim mcycle delta. Suppressed under --cosim: every checkpoint adds a DMI
549	  // halt + drain + resume to the vsim leg, so the delta no longer measures
550	  // the kernel (a --cosim run answers "where diverged", not "how many cycles").
551	  if (!cli.cosim) {
552	    const unsigned long long q_mc = r.phases[0].mcycle;
553	    const unsigned long long v_mc = r.phases[1].mcycle;
554	    std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
555	                trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
556	  }
557	
558	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
559	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
560	  // halt pc, and diff the two drains in-process. The oracle plan gets its
561	  // own fresh mmap: reusing the main run's would boot the oracle on the
562	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
563	  // output was already relayed from the main run.
564	  if (cli.verify) {
565	    char pcbuf[32];
566	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
567	                  static_cast<unsigned long long>(r.phases[1].st.pc));
568	    Trigger vtrig;
569	    vtrig.kind = "verify-" + trig.kind;
570	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
571	    vtrig.params["drain_pc"] = pcbuf;
572	
573	    Plan vplan;
574	    vplan.elf = elf_path;
575	    vplan.mem_size = mem;
576	    vplan.steps = {Step{"qemu", "fast-leg", vtrig}};
577	
578	    std::fprintf(stderr,
579	                 "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
580	                 "exit, pc=%s)\n",
581	                 pcbuf);
582	    const PlanResult vr = run_plan(vplan, disc.engines);
583	    if (!vr.ok()) {
584	      std::fprintf(stderr, "andesim run --verify: %s\n", vr.error.c_str());
585	      return 1;
586	    }
587	    const DiffReport d = diff_states(vr.phases[0].st, r.phases[1].st);
588	    print_diff_report(d);
589	    if (!d.ok()) {
590	      std::fprintf(stderr,
591	                   "andesim run --verify: vsim drain diverges from the "
592	                   "QEMU oracle\n");
593	      return 1;
594	    }
595	    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
596	  }
597	
598	  // --cosim (cosim_roi F4, default off, dev): re-run the ELF on pure QEMU
599	  // with the plugin draining at the vsim checkpoints' retire deltas, then
600	  // diff checkpoint k against checkpoint k and the final drains. minstret is
601	  // restored from the entry state on resume, so `checkpoint.minstret -
602	  // entry.minstret` is the exact post-entry retire count -- both engines
603	  // sample the SAME architectural points, and the first mismatching window
604	  // brackets the divergence. Fresh mmap for the oracle (clean memory);
605	  // stdout dropped (already relayed from the main run).
606	  //
607	  // --cosim-refine (cosim_redesign F7): when set, after the coarse window is
608	  // found the driver re-runs QEMU1->vsim with explicit targets subdividing it
609	  // ~16x per pass (the vsim leg finishes at the last target, so each pass is
610	  // bounded), re-running the oracle at the vsim leg's achieved deltas, until
611	  // the window shrinks to the halt slack. QEMU1 is deterministic, so each pass
612	  // re-derives the same entry state -- no mmap snapshot needed.
613	  if (cli.cosim) {
614	    const unsigned long long m0 = r.phases[0].st.minstret;
615	
616	    // Flatten a leg's checkpoints + final drain into (state, absolute-delta)
617	    // lists. False on a zero/non-ascending delta (a corrupt leg).
618	    auto collect = [&](const PhaseResult& leg,
619	                       std::vector<hybrid_state_v1>& states,
620	                       std::vector<unsigned long long>& deltas) -> bool {
621	      states.clear();
622	      deltas.clear();
623	      for (const hybrid_state_v1& c : leg.checkpoints) {
624	        const unsigned long long d = c.minstret - m0;
625	        if (d == 0 || (!deltas.empty() && d <= deltas.back())) return false;
626	        states.push_back(c);
627	        deltas.push_back(d);
628	      }
629	      const unsigned long long df = leg.st.minstret - m0;
630	      if (df == 0 || (!deltas.empty() && df <= deltas.back())) return false;
631	      states.push_back(leg.st);
632	      deltas.push_back(df);
633	      return true;
634	    };
635	
636	    auto join = [](const auto& xs) {
637	      std::string s;
638	      for (size_t i = 0; i < xs.size(); ++i)
639	        s += (i ? ":" : "") + std::to_string(xs[i]);
640	      return s;
641	    };
642	
643	    // Oracle: pure QEMU draining at the given absolute deltas. Returns its
644	    // states (checkpoints + final, length == counts.size()) or nullopt.
645	    auto run_oracle = [&](const std::vector<unsigned long long>& counts)
646	        -> std::optional<std::vector<hybrid_state_v1>> {
647	      Trigger ot;
648	      ot.kind = "cosim-" + trig.kind;
649	      if (trig.kind == "pc") ot.params["enter_pc"] = trig.params.at("enter_pc");
650	      ot.params["counts"] = join(counts);
651	      Plan op;
652	      op.elf = elf_path;
653	      op.mem_size = mem;
654	      op.steps = {Step{"qemu", "fast-leg", ot}};
655	      const PlanResult orr = run_plan(op, disc.engines);
656	      if (!orr.ok()) {
657	        std::fprintf(stderr, "andesim run --cosim: %s\n", orr.error.c_str());
658	        return std::nullopt;
659	      }
660	      std::vector<hybrid_state_v1> os = orr.phases[0].checkpoints;
661	      os.push_back(orr.phases[0].st);
662	      if (os.size() != counts.size()) {
663	        std::fprintf(stderr,
664	                     "andesim run --cosim: oracle returned %zu states, "
665	                     "want %zu\n",
666	                     os.size(), counts.size());
667	        return std::nullopt;
668	      }
669	      return os;
670	    };
671	
672	    // First index where two aligned state lists differ (trap cause excluded:
673	    // the hybrid ROI is trap-free by contract).
674	    auto first_div = [](const std::vector<hybrid_state_v1>& os,
675	                        const std::vector<hybrid_state_v1>& vs)
676	        -> std::optional<size_t> {
677	      for (size_t i = 0; i < os.size() && i < vs.size(); ++i)
678	        if (!diff_states(os[i], vs[i]).ok()) return i;
679	      return std::nullopt;
680	    };
681	
682	    // ---- pass 1: the interval checkpoints from the main hybrid run ----
683	    std::vector<hybrid_state_v1> vstates;
684	    std::vector<unsigned long long> vdeltas;
685	    if (!collect(r.phases[1], vstates, vdeltas)) {
686	      std::fprintf(stderr,
687	                   "andesim run --cosim: non-ascending vsim checkpoint "
688	                   "deltas (corrupt leg?)\n");
689	      return 1;
690	    }
691	    std::fprintf(stderr,
692	                 "[andesim] cosim: oracle leg (pure QEMU, %zu sample(s))\n",
693	                 vdeltas.size());
694	    const auto ostates = run_oracle(vdeltas);
695	    if (!ostates) return 1;
696	
697	    auto div = first_div(*ostates, vstates);
698	    if (!div) {
699	      std::printf("[cosim] PASS: %zu checkpoint(s) + final state match the "
700	                  "QEMU oracle (interval %llu, %llu ROI retires)\n",
701	                  vstates.size() - 1, cosim_interval, vdeltas.back());
702	      std::printf("PASS: --mode hybrid --trigger %s (%s)\n",
703	                  trig.kind.c_str(), elf.stem().string().c_str());
704	      return 0;
705	    }
706	
707	    // Coarse diverging window (lo, hi]; div_v/div_o are the states at hi.
708	    unsigned long long lo = (*div == 0) ? 0 : vdeltas[*div - 1];
709	    unsigned long long hi = vdeltas[*div];
710	    hybrid_state_v1 div_v = vstates[*div];
711	    hybrid_state_v1 div_o = (*ostates)[*div];
712	    DiffReport div_diff = diff_states(div_o, div_v);
713	
714	    // ---- refine: subdivide (lo, hi] until it reaches the halt-slack floor.
715	    // Targets must stay >= kSpacing apart so the vsim halt overshoot cannot
716	    // reorder the achieved deltas; below that the haltreq checkpoint cannot
717	    // resolve further (use --mode cycle --cosim for exact single-stepping).
718	    if (cli.cosim_refine) {
719	      constexpr unsigned long long kSpacing = 8;
720	      constexpr int kFanout = 16;
721	      int pass = 1;
722	      while (hi - lo > kSpacing) {
723	        const std::vector<uint64_t> targets =
724	            subdivide_window(lo, hi, kFanout, kSpacing);
725	        if (targets.size() < 2) break;
726	        std::fprintf(stderr,
727	                     "[andesim] cosim-refine pass %d: window (%llu, %llu], "
728	                     "%zu probes\n",
729	                     ++pass, lo, hi, targets.size());
730	
731	        Step q{"qemu", "fast-leg", trig};
732	        Step v{acc->id, "accurate-leg", trig};
733	        v.extra_args = {"--hybrid-cosim-at", join(targets)};
734	        Plan p;
735	        p.elf = elf_path;
736	        p.mem_size = mem;
737	        p.steps = {q, v};
738	        const PlanResult pr = run_plan(p, disc.engines);
739	        if (!pr.ok()) {
740	          std::fprintf(stderr, "andesim run --cosim-refine: %s\n",
741	                       pr.error.c_str());
742	          return 1;
743	        }
744	        std::vector<hybrid_state_v1> rv;
745	        std::vector<unsigned long long> rd;
746	        if (!collect(pr.phases[1], rv, rd)) {
747	          std::fprintf(stderr,
748	                       "andesim run --cosim-refine: non-ascending vsim "
749	                       "deltas (halt slack exceeded the probe spacing?)\n");
750	          break;  // report the best window found so far
751	        }
752	        const auto ro = run_oracle(rd);
753	        if (!ro) return 1;
754	        const auto rdiv = first_div(*ro, rv);
755	        if (!rdiv) break;  // no narrower split resolved; keep current window
756	
757	        const unsigned long long nlo = (*rdiv == 0) ? lo : rd[*rdiv - 1];
758	        const unsigned long long nhi = rd[*rdiv];
759	        if (nhi >= hi && nlo <= lo) break;  // no progress
760	        lo = nlo;
761	        hi = nhi;
762	        div_v = rv[*rdiv];
763	        div_o = (*ro)[*rdiv];
764	        div_diff = diff_states(div_o, div_v);
765	      }
766	    }
767	
768	    // ---- report the (narrowed) diverging window ----
769	    print_diff_report(div_diff);
770	    const std::string sym = symbolize(elf_path, div_v.pc);
771	    std::fprintf(stderr,
772	                 "[cosim] FAIL: divergence in retires %llu..%llu after entry "
773	                 "(%llu insn window)%s\n",
774	                 lo, hi, hi - lo, cli.cosim_refine ? ", narrowed" : "");
775	    std::fprintf(stderr, "        at retire ~%llu: pc vsim=0x%llx qemu=0x%llx%s\n",
776	                 hi, static_cast<unsigned long long>(div_v.pc),
777	                 static_cast<unsigned long long>(div_o.pc),
778	                 sym.empty() ? "" : ("   (" + sym + ")").c_str());
779	    if (cli.cosim_refine && hi - lo > 8)
780	      std::fprintf(stderr,
781	                   "        (window at the halt-slack floor; for the exact "
782	                   "instruction use --mode cycle --cosim on a reset testbench)\n");
783	    return 1;
784	  }
785	
786	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
787	              elf.stem().string().c_str());
788	  return 0;
789	}
790	
791	}  // namespace
792	
793	int cmd_run(const Cli& cli) {
794	  if (cli.model.empty()) {
795	    std::fprintf(stderr,
796	                 "andesim run: --mode fast|cycle|hybrid is required\n");
797	    return 2;
798	  }
799	  if (!find_model(cli.model)) {
800	    std::fprintf(stderr,
801	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
802	                 cli.model.c_str());
803	    return 2;
804	  }
805	  if (!cli.gdb_port.empty() && !cli.gdb) {
806	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
807	    return 2;
808	  }
809	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
810	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
811	  if (cli.gdb && cli.model == "hybrid") {
812	    std::fprintf(stderr,
813	                 "andesim run: --gdb is not supported with --mode hybrid\n");
814	    return 2;
815	  }
816	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
817	  // composition has a second engine to check.
818	  if (cli.verify && cli.model != "hybrid") {
819	    std::fprintf(stderr,
820	                 "andesim run: --verify requires --mode hybrid (the %s "
821	                 "model has nothing to cross-check)\n",
822	                 cli.model.c_str());
823	    return 2;
824	  }
825	  // --cosim cross-checks against a QEMU oracle: hybrid (ROI window checkpoints)
826	  // or cycle (lock-step from reset). The fast model is QEMU itself -- nothing
827	  // to check.
828	  if (cli.cosim && cli.model == "fast") {
829	    std::fprintf(stderr,
830	                 "andesim run: --cosim requires --mode hybrid or cycle "
831	                 "(fast is QEMU itself, nothing to cross-check)\n");
832	    return 2;
833	  }
834	  if (cli.cosim && cli.verify) {
835	    std::fprintf(stderr,
836	                 "andesim run: --verify and --cosim are exclusive (--cosim "
837	                 "already cross-checks the final state)\n");
838	    return 2;
839	  }
840	  // --cosim-interval is the hybrid ROI knob; --cosim-max-records is the
841	  // cycle lock-step knob. Each requires --cosim and its own model.
842	  if (!cli.cosim && !cli.cosim_interval.empty()) {
843	    std::fprintf(stderr, "andesim run: --cosim-interval requires --cosim\n");
844	    return 2;
845	  }
846	  if (!cli.cosim_interval.empty() && cli.model != "hybrid") {
847	    std::fprintf(stderr,
848	                 "andesim run: --cosim-interval applies to --mode hybrid "
849	                 "(cycle lock-step uses --cosim-max-records)\n");
850	    return 2;
851	  }
852	  if (!cli.cosim_max_records.empty() && !(cli.cosim && cli.model == "cycle")) {
853	    std::fprintf(stderr,
854	                 "andesim run: --cosim-max-records requires --mode cycle "
855	                 "--cosim (lock-step)\n");
856	    return 2;
857	  }
858	  // --cosim-refine narrows the hybrid ROI window; it has no meaning for the
859	  // cycle lock-step (already exact) or without --cosim.
860	  if (cli.cosim_refine && !(cli.cosim && cli.model == "hybrid")) {
861	    std::fprintf(stderr,
862	                 "andesim run: --cosim-refine requires --mode hybrid "
863	                 "--cosim (cycle lock-step is already instruction-exact)\n");
864	    return 2;
865	  }
866	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window; fast and
867	  // cycle run the whole program and would silently drop them, handing back a
868	  // whole-program figure for the window the user asked for. Reject instead.
869	  // Exception: --pc-start doubles as the cycle lock-step arm pc under
870	  // --mode cycle --cosim (run_cosim_lockstep), so it stays valid there.
871	  if (!cli.trigger.empty() && cli.model != "hybrid") {
872	    std::fprintf(stderr,
873	                 "andesim run: --trigger applies only to --mode hybrid "
874	                 "(the ROI delimiter); fast/cycle run the whole program\n");
875	    return 2;
876	  }
877	  if (!cli.pc_end.empty() && cli.model != "hybrid") {
878	    std::fprintf(stderr,
879	                 "andesim run: --pc-end applies only to --mode hybrid "
880	                 "--trigger pc\n");
881	    return 2;
882	  }
883	  if (!cli.pc_start.empty() && cli.model != "hybrid" &&
884	      !(cli.model == "cycle" && cli.cosim)) {
885	    std::fprintf(stderr,
886	                 "andesim run: --pc-start applies only to --mode hybrid "
887	                 "--trigger pc (or --mode cycle --cosim)\n");
888	    return 2;
889	  }
890	  if (cli.model == "fast") return run_fast(cli);
891	  if (cli.model == "cycle") return run_accurate(cli);
892	  return run_hybrid(cli);  // model validated above; only hybrid remains
893	}
894	
895	}  // namespace andes_sim
