1	// andesim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
2	// and future backends). One C++20 binary that selects a model (fast / cycle
3	// / hybrid), resolves engines at runtime, and either passes through to a single
4	// engine or orchestrates a hybrid round-trip.
5	//
6	// This file owns argument dispatch only: parse the CLI, route to a command.
7	// Each subcommand below resolves to its handler as its feature lands (F1-F13);
8	// until then it stubs out, keeping the command surface stable.
9	#include <cstdio>
10	#include <cstdlib>
11	#include <exception>
12	#include <string>
13	#include <string_view>
14	
15	#include "cli.hpp"
16	#include "dev_mode.hpp"
17	#include "repo_root.hpp"
18	
19	namespace andes_sim {
20	int cmd_list(const Cli& cli);
21	int cmd_doctor(const Cli& cli);
22	int cmd_run(const Cli& cli);
23	}  // namespace andes_sim
24	
25	namespace {
26	
27	using andes_sim::Cli;
28	using andes_sim::is_dev_mode;
29	
30	// Each command's release tier decides where it shows in `--help`:
31	//   Release -- the finished, user-facing product surface (always listed).
32	//   Hidden  -- a stable dispatch slot for an unfinished ROADMAP feature; never
33	//              listed (explicit invocation still hits the "not yet implemented"
34	//              stub), so the product never advertises half-built work.
35	// Developer build/test/state-diff tooling lives in scripts/, not the binary.
36	enum class Tier { Release, Hidden };
37	
38	struct Subcommand {
39	  std::string_view name;
40	  std::string_view brief;
41	  Tier tier;
42	};
43	
44	// The full command surface. Names are fixed from F0 so usage, dispatch, and
45	// tests are stable; handlers arrive feature by feature. The tier (above) keeps
46	// unfinished commands out of the release `--help` (see print_usage). Listed
47	// release-first, then hidden -- dispatch is by name, so the order is purely the
48	// display order.
49	constexpr Subcommand kSubcommands[] = {
50	    {"run", "run one simulation (--mode fast|cycle|hybrid)", Tier::Release},
51	    {"list", "list models|engines", Tier::Release},
52	    {"doctor", "check environment health", Tier::Release},
53	    {"profile", "profile a workload into a basic-block vector", Tier::Hidden},
54	    {"cluster", "cluster a BBV into SimPoint phases", Tier::Hidden},
55	    {"archive", "snapshot a drained state into a replayable dir", Tier::Hidden},
56	    {"replay", "replay a snapshot", Tier::Hidden},
57	    {"estimate",
58	     "whole-program cycle estimate (run --mode hybrid --trigger simpoint)",
59	     Tier::Hidden},
60	};
61	
62	const Subcommand* find(std::string_view name) {
63	  for (const Subcommand& s : kSubcommands)
64	    if (s.name == name) return &s;
65	  return nullptr;
66	}
67	
68	void print_command(std::FILE* out, const Subcommand& s) {
69	  std::fprintf(out, "  %-9.*s  %.*s\n", static_cast<int>(s.name.size()),
70	               s.name.data(), static_cast<int>(s.brief.size()), s.brief.data());
